import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷十七","description":"周易經傳集解 - 周易經傳集解卷十七","frontmatter":{"title":"周易經傳集解卷十七","description":"周易經傳集解 - 周易經傳集解卷十七"},"headers":[],"relativePath":"classics/jingchuan-jijie/018.md","filePath":"classics/jingchuan-jijie/018.md"}'),r={name:"classics/jingchuan-jijie/018.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷十七",tabindex:"-1"},[n("周易經傳集解卷十七 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷十七","aria-label":"Permalink to “周易經傳集解卷十七”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解遁大壯卷十七 ​宋林栗撰序卦曰：恆者，久也。物不可以久居其所，故受之以「遁」。「遁」之成卦，恆之變也。自「恆」之「遁」，二、五相易，變其上爻而成「遁」也。二、五相易，則乾巽不交矣。變其上爻，則陽剛居外矣。夫乾以三陽而降於三陰之中，雖剛柔上下，進退無常，然皆內陽而外陰，內健而外順，是以為「鹹」、為「恆」也。今二、五變而不交，上九出而居外，則是內陰而外陽，內柔而外剛矣，是以謂之「遁」也。「遁」之言退也，二陰浸長，得位居內，四陽雖盛，失勢居外，小人進而君子退也。主君子而言，是故以「遁」名之。君子也者，知進退存亡而不失其正，消息盈虛，與時偕行者也。四陽見二陰之長，遁而去之，所以全其剛也。或曰：三陰長而為「否」，五陰極而為「剝」，君子猶居其間。二陰方長，四陽未衰，曷為「遁」哉？曰：「否」陰三，故自四以往，君子居之；剝陰窮於五，故上九一爻，君子居之。遁陰方長，未可與爭君子，是以見幾而作也。今夫泰交之世，非盡滅小人而獨生君子也，小人變而為君子也。否剝之世，非盡滅君子而獨生小人也，君子化而為小人也。故一陰之生，則曰「不可與長也」；二陰之生，則曰「浸而長也」。若三陰之長，則君子之黨半為小人，其道消矣。故夫知幾之君子，見二陰之浸長，懼為所消，是以遁而去之也。苟晏安酖毒，懷祿不去，則日朘月削，陷於柔邪而不自知矣。二陰而遁，不亦宜乎？遁：亨，小利貞。彖曰：「遁亨」，遁而亨也。剛當位而應，與時行也。「小利貞」，浸而長也。遁之時義大矣哉！下艮上乾。成卦曰「遁」者，初為艮，二為巽，三四為乾。乾，陽也，艮亦陽也。同類相從，固其所也，又何遁哉？乾，健也；艮，止也。下止而應，上健而行，斯其志矣，又何遁哉？為其有巽之象焉。巽為入為伏，而在下卦之中，乾之所為「遁」也。彼以柔巽之道，既入而伏其中矣，而乃以高爵重祿啖我以利，甘辭媚色，陽為深交。君子於此，可不遁而去之乎？何者？其措心積慮，惟欲吾道之消也。「遁亨」何謂也？曰：遁非可亨之時，能遁而後亨也。於斯之時，苟不知遁，則君子之道日消而盡，何自亨哉？「否」之六二亦曰「大人否」，否則不亨也。夫以九五當位，而有六二為之應，然而遁者何也？消息盈虛，與時偕行也。君子履霜而知堅冰之漸，可以牽於系應而不自為去就也哉？故曰「尺蠖之屈，以求伸也；龍蛇之蟄，以存身也；君子之遁，以求亨也」。「小利貞」何謂也？曰：陽為大，陰為小。方遁之時，二陰浸長而皆有其應。六二居中，而巽以承上，以此為貞，小人之利也。夫所惡於二陽者，為其浸長而不可遏也。苟貞於此，則小人在下，而君子在上，何不利之有哉？是故泰之二、五，則「利君子貞」，否之二、五，則「不利君子貞」。「遁」之二、五，猶「小利貞」，不可以大有為也。夫九五、六二三卦不殊，則君子、小人之貞有利不利焉，可不深求其故哉？故子曰：「遁亨，遁而亨也。剛當位而應，與時行也。小利貞，浸而長也。遁之時義大矣哉！」蘇氏曰：遁非避患之遁，以為非遁無以反乎其君之心也。今二陰在內，而其勢至銳，而其朋至寡。銳則其終必至於勝，寡則其心常欲得眾。聖人畏其有必勝之漸，而知其乖眾之意，是以使陽遁陰。陽皆遁，則陰無與處，而思求陽，陰思求陽，而後陽可以處，此遁之所由亨也。蘇氏此論，是非相雜，近於押闔要君者之所為。懼學者之易流，不可以訓，故為正之。夫二陰方銳，其黨未強，而其勢必勝。與之爭，則吾道必消，不爭亦必消。惟遁而去之，則可以全剛也。非獨可以全吾之剛，亦足以悟君之感也。四陽既遁，陰無能為，危莫與持，顛莫與扶，則將反之而為「大壯」矣。故聖人作易，以「壯」繼「遁」。蓋言二陰之世，君子能遁，則「大壯」有反掌之易。惟其懷祿不能遁去，則日消而為陰，陰遂強盛而不可救耳。苟已遁而君猶不悟，則如之何？曰：遁而不悟，則「否」之象見矣。險德避難，斯亦可矣，又何求哉？故齊歸女樂三日，而夫子出走，猶曰「遲遲吾行」，蓋有所待焉爾。孟軻三宿出晝，而齊王不追，然後浩然有歸志也。而蘇氏以為非避患之遁，是豈要君之遁乎？又謂「陰思求陽，則陽可以處」。夫陰之用事，未嘗不思求陽也。求而與之者，是為其所消也。故「遁」之九四、九五，皆有正應，與之嘉好，脫身而去，莫之肯留者，畏其消也。苟曰「陰思求陽，則陽可以處」，如是則小人為主，君子為客，遁何自亨哉？由遁而為大壯，亨之義也。王叔文用事，以杜佑故相，名高位重，使領度支，而己為之副。君子觀此之象，可以不遁乎哉？賈耽、鄭珣瑜去之晚矣。象曰：天下有山，「遁」。君子以遠小人，不惡而嚴。天者，「乾」也；山者，「艮」也。山從地而高，極其崇峻，疑若陵於天矣。然天益高遠，終非山之所能陵也。君子之於小人，豈將惡而絕之哉？草木禽獸，無所不愛，而況人乎？「近之則不遜，遠之則怨」，小人之常態也。「不可得而親，不可得而疏」，君子之道也，是天山之象矣。天之所以遠於山者，以其尊也；君子所以遠於小人者，以其嚴也。惡之則怨，不嚴則瀆。怨則召禍，瀆則招侮。不惡而嚴，小人自遠矣。故子曰：「苟志於仁矣，無惡也。人而不仁，疾之已甚，亂也。」是不惡之義也。動容貌，斯遠暴慢矣；出辭氣，斯遠鄙倍矣，嚴之義也。是故君子有三變，望之儼然，即之也溫，聽其言也厲，其守身之道歟？雜卦曰：「遁則退也。」「遁」之為卦，以二陰浸長而成。其在六爻，以陰進陽退為義。夫陰陽之相為進退，如晝夜寒暑之常。然方其進也，一用而有餘；及其退也，五存而不足。「復」、「姤」是也，而況於「臨」、「遁」乎？夫「臨」之世，四陰在上，而不能禁二陽之長；則「遁」之世，四陽在上，將何以御二陰之衝乎？然君子之於小人，有覆育之心，而無疾惡之意，是以其卦為「臨」。小人之於君子，無忠信之實，而有詐諼之情，是以其卦為「遁」也。初六有「遁尾」之厲，六二有「牛革」之堅，陰進之爻也。九三「系遁」，九四「好遁」，九五「嘉遁」，上九「肥遁」，其四陽之退乎？初六：遁尾，厲，勿用有攸往。象曰：「遁尾」之「厲」，不往何災也？初六，「艮」也，以陰居剛，而在下卦之下，應乎九四。四，「乾」兌也，故曰「遁尾」。「兌」，西方之卦，有虎之象焉。自兌而「乾」，由西而北，「遁」之勢也。易以上為首，初為尾，遁自內之外，故初六為「遁」之尾。夫六二在「遁」之世，小人居中而用事者也；初六在「遁」之世，小人在下而圖進者也。小人進則君子遁矣。方遁之時，四陽外向，而初蹙其尾，迫之使遁也，故曰「厲」。又曰：「勿用有攸往。」夫猛獸之遁也，妥其尾而莫敢逐，或者從而蹙之，其首必反，不亦厲乎？為其體「艮」而居下，故戒以「勿用有攸往」而已。「大壯」之上六，「遁」之初六也；「大壯」之六五，「遁」之六二也。六二用事，故在「壯」則「喪羊」而「無悔」；初六方進，故在「壯」則觸藩而「無攸利」。聖人知遁有反壯之理，故以尾為象，而戒之「勿往」。初六不往，而順以承上，豈有羝羊觸藩之禍乎？故子曰：「遁尾之厲，不往何災也？」聖人之愛君子而懲小人至矣。六二：執之用黃牛之革，莫之勝說。象曰：執用黃牛，固志也。六二，「巽」也，以陰居柔而在下卦之中，應乎九五之「乾」，故曰：「執之用黃牛之革，莫之勝說」。「執」，讀如縶。「乾」為馬，「巽」為繩，故有「縶之」之象。「黃」者，中也。「牛」，順物也。「革」，柔而堅也。九五將「遁」，六二居中而「巽」以系之，故有「黃牛之革」之象。小人用事，暗而無謀，輕而寡信，令而民莫之從，威而民莫之服，故雖得君而行政，不能以自為也，必賴君子以濟其欲，求得欲從，然後惟其所為而莫敢不聽矣。故六二上應九五，「巽」以從之，冀其為己留也。然君子知彼得志則吾道日消，是以翻然說而去之，「好遁」、「嘉遁」是也。小人懼君子之去，至於用其忠順之道、柔巽之情、堅固之意，執而留之而不可得也。譬如以黃牛之革系焉，而不勝其說，君子之知幾而不懷祿如此。故子曰：「執用黃牛，固志也。」言小人非能忠順也，用其忠順以固君子之心耳。可不察歟？九三：系遁，有疾，厲。畜臣妾，吉。象曰：「系遁」之利，有疾憊也；「畜臣妾，吉」，不可大事也。九三上體為「乾」，下體為「震」，以陽居剛而在下卦之上，上無其應，而連於六二之「巽」，故曰「系遁」。「巽」為繩，故有「系」象。震、「巽」，配也；「乾」，遇也。四陽皆「遁」，而九三最系，又比於二而繫於「巽」焉，是以謂之「系遁」也，故曰「有疾厲」。疾者，害也。九三將遁，而物或害之，六二是也。君子之靜也，介於石，其動也不終日。仲尼之去魯也，不稅冕而行；去齊也，接淅而行；去衛也，明日遂行。今以陽居剛而體乎乾震，見二陰之長，將欲遁而去之，有所繫而不得去，危之道也。陰長而陽消，九三先及，是以在「遁」為「疾」，在「否」為包羞。故子曰：「系遁之厲，有疾憊也。」「憊也」者，言其無勇也。傳曰：「執狐心之疑者，來讒賊之口；持不斷之意者，開群枉之門。」九三之謂矣。故曰：「畜臣妾，吉。」夫九三於「遁」，固為有疾，若以遁為「畜臣妾」之卦，則三為「吉」。何者？以上而臨下，以剛而制柔，以乾震而遇巽，則無倒持之弊矣。或曰：名卦曰「遁」，豈得以遁為「畜臣妾」之卦乎？曰：易窮則變，變則通，所以極天下之動也。「剝」之六五，豈非剝及尊位乎？乃以剝為「寵宮人」，以卦五陰而奉一陽，魚貫而進，則六五之象無不利矣。「遁」之九三，當二陰之進，有危厲之象。若以遁為「畜臣妾」之卦，四陽而臨二陰，堂階尊嚴，則九三之象，斯為言矣。離之「畜牝牛吉」，亦猶是也。是以穆姜之筮，得「元亨利正」而薨；南蒯之筮，得「黃裳元吉」而敗。學易者其可以不知此哉？故子曰：「畜臣妾吉，不可大事也。」上尊而下卑，可以畜臣妾而已。若當大事，而小人在內，君子在外，尊不下際，而卑不上行，其能濟乎？彖之所以有「小利貞」之辭也。九四：好遁，君子吉，小人否。象曰：君子「好遁」，「小人否」也。九四上體為「乾」，下體為「兌」，以陽居柔而在上卦之下，應乎初六之「艮」，故曰「好遁」。「好」，情好也。下「艮」上「兌」，有二少相感之象焉。體乎剛健，舍之而去，是以謂之「好遁」也。故曰：「君子吉，小人否。」以「兌」則應乎「艮」，以「乾」則無應。「乾」為君子，「兌」為小人。君子見幾而作，不為情好之所牽，斯為吉矣。小人唯利是視，而豈能然哉？在卦四陽為君子，而君子之中不能無小人焉，則以其體乎「兌」故也。陰欲消陽，而陽不能遁也，此其所以為「否」也。九五、六二，下「艮」上「兌」，其辭曰：「小人吉，大人否，亨。」雖若相反，其義一也。蓋「好遁」者，君子之吉；而「包承」者，小人之吉也。君子之否，所以求亨；小人之否，則無自而亨矣。故子曰：「君子好遁，小人否也。」大壯九三「小人用壯，君子罔也」之義同。說者或以為「臧否」之「否」，或以為「可否」之「否」，於義亦通。但以由「遁」而「否」，當是本義。易之取義，不一而足。若「遁」者，非獨見其不為情好之所牽，亦不惡而嚴之意也。五之「嘉遁」，亦猶是爾。九五：嘉遁，貞吉。象曰：「嘉遁，貞吉」，以正志也。九五，「乾」也。以陽居剛，而在上卦之中，應乎六二之「巽」，故曰「嘉遁」。「嘉」，配偶也。九五、六二，「乾」「巽」相應，故有「嘉偶」之象。夫情好之私，或非其正，舍之而去，猶若易然。至於伉儷之情，室家之義，幡然而改，亦已難矣，故曰「貞吉」。以此為貞，斯為吉也。何者？九五、六二，上乾下巽，有相應之形，而無相與之意也。或曰：「遁」之九五，非君位歟？曰：何為其然也？九五非君，則六二無應，不得為用事之臣矣。爻以象變，辭以爻變，豈特一端而盡之乎？故曰：「嘉遁貞吉，以正志也。」夫君子與小人，如冰炭之不侔，薰蕕之不併，所以耽於情好，牽於系應，而陷溺其良心者，貪權嗜利而不能自脫故也。孟子有言：「卿為身死而不受，今為宮室之美為之；卿為身死而不受，今為妻妾之奉為之；卿為身死而不受，今為所識窮乏者得我而為之。」此之謂失其本心。然則五之「嘉遁」，君子所以正其志而已矣。彼雖欲固吾志之留，吾乃欲正吾志之遁，是以執用黃牛而莫之勝也。或曰：何謂君子與小人為好，又與之為配乎？曰：假如邪佞小人得君而用事，外之諸臣與之姻婭，則是「好」也。職相監臨，位相統攝，彼有寵於中而善載於外，則是「嘉」也。能捨而遁，不亦君子之吉乎？孔子在衛，彌子之婁與子路之妻兄弟也。彌子謂子路曰：「孔子主我，衛卿可得也。」子路以告，孔子曰：「有命。」孟子為卿於齊，出吊於滕，王使蓋大夫王𬴐為輔行。王𬴐朝暮見，反齊、滕之路，未嘗與之言行事也。唐李鄘節度淮南，與監軍吐突承璀相敬憚，由是厚善。承璀有寵於憲宗，薦之，召相鄘，鄘不喜，由承璀進，引疾固辭而罷。「好遁」、「嘉遁」，其斯人之謂歟？上九：肥遁，無不利。象曰：「肥遁，無不利」，無所疑也。上九，「乾」也。以陽居柔，下無所應，上無所與，而在一卦之外，故曰「遁」。「肥遁」，非君子之慾也。君臣猜間而道不得行；小人得志而禍將及身，故退藏以避之，可謂君子憂患之時矣。憂患之至，雖飽食而弗肥；及其無憂，雖簞瓢而匪瘠。九三之「系遁」，九四之「好遁」，九五之「嘉遁」，皆未離乎憂患之域，雖欲肥，不可得也。惟上九一爻，超然於塵垢之外，無足以累其心而疑其志者，謂之「肥遁」，不亦宜乎？故曰：「無不利。」子曰：「肥遁無不利，無所疑也。」揚子云曰：「山雌之肥。」其意得乎？釋「肥遁」之義，得矣。序卦曰：遁者，退也。物不可以終遁，故受之以大壯。大壯成卦，遁之反也。自遁之壯，乾反居下，艮變為震也。乾反居下，則內健而外順矣；艮變為震，則小往而大來矣。四陽得位而居內，二陰失勢而居外，既大且壯，是以謂之「大壯」也。或曰：陰陽消長，必極其所至而後反。二陰之月，反為四陽，天道之行，未嘗有是，而聖人象之，何哉？曰：然。消息盈虛者，天之行也；撥亂反正者，聖人之功也。如使存亡治亂，必極其所至而後反，則何尊乎聖人？何貴乎君子？何尚乎六經哉？是以乾至上九而受之以用九，坤至上六而受之以用六。窮則變，變則通，易之所為作也。故曰：「亢龍有悔，興時偕極。乾元用九，乃見天則。」此聖人之志也。自遁而壯，亦猶是乎？大壯，利貞。彖曰：大壯，大者壯也。剛以動，故壯。「大壯利貞」，大者正也。正大而天地之情可見矣。下乾上震，成卦曰「大壯者，初為乾，二亦為乾，三為兌，四為震。乾，健也；震，動也。陽為大，陰為小；陽為壯，陰為羸。乾震皆陽也，斯謂之大壯矣乎？曰：物之大小，生於相形，勢之強弱本於相輕。若乾與震相遇，則無餘象，而謂之大壯，是乾為大而震為小矣，乾為壯而震為羸矣。為其有兌象焉，為震兌者一，為乾者二，為偶者二，為奇者四，是以謂之大壯也。故曰大壯，大者壯也，剛以動，故壯也。大壯利貞」，何謂也？曰：貞者，正也。凡易言「貞」與「徵」為相反之辭。徵猶往也，貞猶正也，無平不陂，無往不復。當大壯之時，四陽在內，二陰在外，此強而彼弱矣。惟君子能守其正而不迫於小人，則小人亦安其分而不謀於君子，如是足矣。苟恃其強而不思正固之道，則自壯而未可知也。故曰「大壯則止，遁則退也」。夫剛以動而系之止，為其卒乎艮故也。君子當遁之時，二陰在內，則可退而不可進；及壯之時，二陰在外，則可止不可徵。夫聖人非不欲天下皆君子也，以為陰陽消長如晝夜寒暑然，窮則變矣。故三陽為泰，而戒以「無往不復」；四陽為壯，而戒以「利貞徵兇」；五陽為夬，而戒以「莫夜有戎」者，畏其窮也。子曰：「大壯，利貞。」大者，正也，正大而天地之情可見矣。君子以正守其大，則其壯莫弊，其動也，孰能御之？於斯之時，福善禍淫之戒可得而窺，好生惡殺之意可得而察，裒多益寡、扶弱抑強之理可得而驗，故曰：「復，其見天地之心乎？」「正大而天地之情可見矣。」老子曰：「物壯則老，是謂不道，不道早已。」夫所為食者，為飽也，飽而生疾者有之，以懲疾而廢飽者，老氏之論也，然亦可以為戒矣。象曰：雷在天上，「大壯」，君子以非禮弗履。雷者，「震」也。天者，「乾」也。雷行天下，則物被其災；雷在天上，震驚而已。是故君子以禮自防，不傷於物，所以全其壯也。恃其壯而妄行，其為遁也猶反掌耳。子路問強，子曰：「南方之強與？北方之強與？寬柔以教，不報無道，南方之強也。」君子居之，非禮弗履，斯為大壯矣。雜卦曰：「大壯則止。」大壯為卦，以四陽二陰而成。其在六爻，以各止其所為義。陽止而不迫於陰，陰止而不抗於陽，如大壯之時，則可矣。夫天下不可一日無君子也，無君子莫治小人；不可一日無小人也，無小人莫養君子。然君子常寡，而小人常眾。故陽數常奇，而陰數常偶也。聖人之心，豈惟不欲小人之勝君子，亦不欲君子之勝小人。何者？天道好還，未有窮而不變者也。當「大壯」之時，雖四陽而二陰，然以其數考之，多寡適足以相當。多寡足以相當，是君子之徒半於天下也。君子之徒半於天下，是天下皆君子也。如是而止焉，君子、小人相與以治，不亦可乎？是以「大壯」諸爻，以陰居剛，以陽居柔者，皆不爭而相與者也。以陰居柔，以陽居剛者，皆不相與而至於爭者也。止則為吉，爭則為兇。「大壯」之君子，豈不念哉？初九：壯於趾，徵兇，有孚。象曰：「壯於趾」，其孚窮也。初九，「乾」也。以陽居剛，而在下卦之下，上無其應，而承於九二。二亦「乾」也，「乾」為健，故曰「壯於趾」。「壯於趾」者，其進銳也。「大壯」之君子，既得其位矣，然猶有「壯趾」之象，何也？在下而求進者也，故曰：「徵兇，有孚。」初既無應於上，所以徵者，其將迫九四而奪之權乎？兇之道也。然居最下之地而敢於「孚」，上人其必有所「孚」矣。初九以陽居剛，其所與者，必以陰居柔者也。在卦六爻，以陰居柔，上六而已。上六，小人之勢窮者也。天下之禍常生於小人之窮，而君子之嗜進者，常出力而為之助，是以深懲而痛艾之也。詩曰：「大風有隧，貪人敗類。」其是之謂乎？故曰：「壯於趾，其孚窮也。」繋辭曰：「上古穴居而野處，後世聖人易之以宮室，上棟下宇，以備風雨，蓋取諸大壯。」何也？君子之所以為壯者，壯於宮室，壯於藩籬，壯於輿輹，屹然有不可動之勢，則風雨鳥鼠不能入其舍，艱難險阻不能改其度，斯為壯矣。苟壯於趾，欲進而不休，豈不易窮哉？由是觀聖人一字之義，其訓周矣。九二：貞吉。象曰：「九二貞吉」，以中也。九二，「乾」也，以陽居柔而在下卦之中，應乎六五之「巽」，故曰「貞吉」。「貞」者，正也。「乾」「巽」之相遇，剛柔之相與，斯為正矣。九二止其健而不爭，六五喪其羊而無悔，二者相濟，不失乎中行，此所以為「吉」也。故曰：「九二貞吉，以中也。」九三：小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。象曰：「小人用壯」，君子罔也。九三上體為「兌」，下體為「乾」，以陽居剛而在下卦之上，應乎上六之「艮」，故曰：「小人用壯，君子用罔。」「罔」，不用也。乾為君子，「兌」為小人，以「兌」則應乎「艮」，故有用壯之象；以「乾」則無應，故有不用之象。夫壯也者，君子之所以自防也。從而用之，以與物角，則喪其所以為壯者矣。然以九居三，非常能不用者也，故曰「貞厲」。羝羊觸藩，羸其角。「兌」為羊。羊之為畜，其生易藩。羝則「不」字之羊也。以「兌」應「艮」，宜有相與之情，而九三、上六，陰陽偏勝，無孳乳之道，是以謂之「羝羊」也。按漢書：「匈奴使蘇武牧羝，羝乳乃得歸。」注曰：「羝，牡也。牡羊不能乳也。」「乳猶有配合之道，非絕其類者也。」羝是「不」字之羊，是以九三、上六皆稱「羝」也。羊狠而好鬥，群居則喜觸。羝羊無牝牡之道，飽食無為，所以用其壯者，惟觸而已。九三之羝將觸，上六閡於九四而難進，故有觸藩羸角之象。「大壯」之君子，苟以九三為「貞」，斯有羸角之禍矣，此其所以為「厲」也。故子曰：「小人用壯，君子罔也。」九四：貞吉，悔亡。藩決不羸，壯於大輿之輹。象曰：「藩決不羸」，尚往也。九四上體為「震」，下體為「乾」，以陽居柔，而在上卦之下，下無其應，而承於六五之「巽」，故曰：「貞吉悔亡。」四之「貞吉」，與二均耳。所以有「悔」者，不中故也。「乾」「巽」遇也，「震」「巽」配也。乾震合體以承乎「巽」。彖之所謂「剛以動故壯」是也。六五之於九四，受而不逆，故曰：「藩決不羸」。陽以四為藩，陰以五為藩。九三之來，其藩設矣。九四之來，其藩既決，則四之角不羸。故曰：「壯於大輿之輹。」輹，輿下橫木也。「坤」為大輿，「震」之一畫在「坤」之下，故有「輿輹」之象。輹壯則輿壯矣，輿壯則可以行矣。所以然者，九四不用其壯，故能使六五自決其藩，所謂不爭而善勝者也。無觸藩之羸，而有輿輹之壯焉，往而不利？故子曰：「藩決不羸，尚往也。」自四而往，其為「夬」乎？「夬」雖五陽，而一陰在上，窮則反矣。是以君子安於壯而危於「夬」也。或曰：三以體兌為羊，故有羸角之象。四，乾震也，而系之不羸，何哉？曰：此相因而成文也。三以用壯，故取羊以為之象。自四以往，雖無兌象，然皆以陰陽相觸，言「大壯」之義。六五者，「兌」之反也，故為「喪羊」。三之所敵者四，是以皆稱羊也。牝馬龍戰，亦猶是矣。六五，喪羊於易，無悔。象曰：「喪羊於易」，位不當也。上六，羝羊觸藩，不能退，不能遂，無攸利，艱則吉。象曰：「不能退，不能遂」，不詳也；「艱則吉」，咎不長也。六五，巽也，以陰居剛而在上卦之中；上六，艮也，以陰居柔而在上卦之上。應乎九三而止，斯為吉矣。故子曰：「不能退，不能遂，不詳也；艱則吉，咎不長也。」此與臨之「六三，咎不長也」之義同。九三之君子既用罔矣，而又曰貞厲；上六之小人既觸藩矣，而又曰「艱則吉」，此則聖人深探物情，知艮、兌二少不能持久，故防其漸而開其自新也。使九三壯而知「厲」，上六困而知「艱」，則大壯之勢，夫孰能御之哉！「詳」字依鄭、王本作「詳」。周易經傳集解卷十七。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
